2	import type { ToolStep } from "@/components/chat/ToolActivityDisclosure";
3	
4	/** What a message renders, in stream order. Consecutive tool/data parts merge into one card. */
5	export type Segment =
6	  | { kind: "text"; text: string; key: string }
7	  | { kind: "reasoning"; text: string; key: string }
8	  | { kind: "tools"; steps: ToolStep[]; callIds: string[]; key: string }
9	  /**
10	   * A tool call paused until the user approves or denies it. For a call a delegated sub-agent
11	   * made, toolName/label/input describe that nested call and `agent` names the sub-agent.
12	   */
13	  | { kind: "approval"; approvalId: string; toolName: string; label: string; input: unknown; agent?: string; key: string };
14	
15	/** Agent display names by registry key and id, for "agent-<key>" delegation tools. */
16	export type AgentNames = Record<string, string>;
17	
18	/** Client-observed tool timing (the stream carries none): first seen → first finished. */
19	const toolTimes = new Map<string, { start: number; end?: number }>();
20	
21	export function messageSegments(message: UIMessage, agentNames: AgentNames): Segment[] {
22	  const segments: Segment[] = [];
23	  const approvalData = toolCallApprovalData(message);
24	  message.parts.forEach((part, index) => {
25	    const key = `${message.id}:${index}`;
26	    if (isTextUIPart(part)) {
27	      if (part.text.trim()) segments.push({ kind: "text", text: part.text, key });
28	      return;
29	    }
30	    if (isReasoningUIPart(part)) {
31	      if (part.text.trim()) segments.push({ kind: "reasoning", text: part.text, key });
32	      return;
33	    }
34	    if (isToolUIPart(part) && part.state === "approval-requested") {
35	      const toolName = getToolName(part);
36	      // A delegated sub-agent's call surfaces on the "agent-<key>" delegation call; Mastra sends
37	      // the real nested tool and arguments for the same call id (see toolCallApprovalData).
38	      const nested = toolName.startsWith("agent-") ? approvalData.get(part.toolCallId) : undefined;
39	      segments.push(
40	        nested
41	          ? {
42	              kind: "approval",
43	              approvalId: part.approval.id,
44	              toolName: nested.toolName,
45	              label: toolLabel(nested.toolName, agentNames),
46	              input: nested.args,
47	              agent: agentName(toolName, agentNames),
48	              key,
49	            }
50	          : {
51	              kind: "approval",
52	              approvalId: part.approval.id,
53	              toolName,
54	              label: toolLabel(toolName, agentNames),
55	              input: part.input,
56	              key,
57	            },
58	      );
59	      return;
60	    }
61	    let step: { step: ToolStep; callId: string } | null = null;
62	    if (isToolUIPart(part)) {
63	      const status =
64	        part.state === "output-denied"
65	          ? "denied"
66	          : part.state === "output-error"
67	            ? "error"
68	            : part.state === "output-available"
69	              ? "done"
70	              : "running";
71	      step = { step: { label: toolLabel(getToolName(part), agentNames), count: 1, status }, callId: part.toolCallId };
72	      track(part.toolCallId, status !== "running");
73	    } else if (isDataUIPart(part) && part.type.startsWith("data-tool-agent")) {
74	      // Mastra sub-agent progress parts; shape varies, so only a safe label is shown.
75	      const data = (part.data ?? {}) as Record<string, unknown>;
76	      const name = typeof data.name === "string" ? data.name : typeof data.agentName === "string" ? data.agentName : null;
77	      step = { step: { label: name ? `${name} working` : "Sub-agent step", count: 1, status: "done" }, callId: key };
78	    }
79	    if (!step) return; // step-start, sources, files and unknown parts render nothing.
80	    const last = segments.at(-1);
81	    if (last?.kind === "tools") {
82	      last.steps.push(step.step);
83	      last.callIds.push(step.callId);
84	    } else {
85	      segments.push({ kind: "tools", steps: [step.step], callIds: [step.callId], key });
86	    }
87	  });
88	  return segments;
89	}
