91	function track(callId: string, finished: boolean) {
92	  const now = Date.now();
93	  const time = toolTimes.get(callId) ?? { start: now };
94	  if (finished && time.end === undefined) time.end = now;
95	  toolTimes.set(callId, time);
96	}
97	
98	/** Wall time across a card's tool calls, when all of them were watched finishing. */
99	export function toolsDurationMs(callIds: string[]): number | undefined {
100	  const times = callIds.map((id) => toolTimes.get(id));
101	  if (times.some((t) => !t || t.end === undefined)) return undefined;
102	  const start = Math.min(...times.map((t) => t!.start));
103	  const end = Math.max(...times.map((t) => t!.end!));
104	  return end - start;
105	}
106	
107	type ApprovalData = { toolName?: unknown; args?: unknown; toolCallId?: unknown };
108	
109	/**
110	 * The tool name and arguments Mastra reports for each call awaiting approval, by tool call id. On
111	 * a live stream they arrive as "data-tool-call-approval" parts (never rendered themselves); in
112	 * loaded history they are the stored `metadata.pendingToolApprovals` entries, keyed by call id.
113	 */
114	function toolCallApprovalData(message: UIMessage): Map<string, { toolName: string; args: unknown }> {
115	  const byCallId = new Map<string, { toolName: string; args: unknown }>();
116	  const add = (callId: unknown, data: ApprovalData) => {
117	    if (typeof callId !== "string" || typeof data.toolName !== "string" || !data.toolName) return;
118	    byCallId.set(callId, { toolName: data.toolName, args: data.args });
119	  };
120	  const pending = (message.metadata as { pendingToolApprovals?: unknown } | undefined)?.pendingToolApprovals;
121	  if (pending && typeof pending === "object") {
122	    for (const [callId, entry] of Object.entries(pending)) {
123	      const data = (entry ?? {}) as ApprovalData;
124	      add(typeof data.toolCallId === "string" ? data.toolCallId : callId, data);
125	    }
126	  }
127	  for (const part of message.parts) {
128	    if (!isDataUIPart(part) || part.type !== "data-tool-call-approval") continue;
129	    const data = (part.data ?? {}) as ApprovalData;
130	    add(typeof data.toolCallId === "string" ? data.toolCallId : part.id, data);
131	  }
132	  return byCallId;
133	}
134	
135	/** "agent-cfoAgent" → "Delegated to CFO Agent"; "crustdataCompanyEnrich" → "Crustdata company enrich". */
136	export function toolLabel(toolName: string, agentNames: AgentNames): string {
137	  if (toolName.startsWith("agent-")) return `Delegated to ${agentName(toolName, agentNames)}`;
138	  return humanize(toolName);
139	}
140	
141	/** "agent-githubAgent" → "GitHub Agent". */
142	function agentName(toolName: string, agentNames: AgentNames): string {
143	  const key = toolName.slice("agent-".length);
144	  return agentNames[key] ?? humanize(key);
145	}
146	
147	function humanize(name: string): string {
148	  const words = name
149	    .replace(/[-_]+/g, " ")
150	    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
151	    .trim()
152	    .toLowerCase();
153	  return words.charAt(0).toUpperCase() + words.slice(1);
154	}
155	
156	/** Plain text of a message, for previews and copy. */
157	export function messageText(message: UIMessage): string {
158	  return message.parts
159	    .filter(isTextUIPart)
160	    .map((part) => part.text)
161	    .join("\n")
162	    .trim();
163	}
