// Temporary verification of the per-user file workspace through the real handleChat path.
// Usage: DATA_DIR=<tmp> npx tsx <this> phase1|phase2   (run from the repo root)
import http from "node:http";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { MockLanguageModelV3 } from "ai/test";

const REPO = "/Users/apple/Open/nlhack";
const phase = process.argv[2] ?? "phase1";
const DATA = process.env.DATA_DIR!;
if (!DATA) throw new Error("DATA_DIR required");

const { mastra } = await import(`${REPO}/src/mastra/index.ts`);
const { handleChat } = await import(`${REPO}/src/chat-api.ts`);

type Step = { tool: string; args: unknown } | { text: string };
const queues: Record<string, Step[]> = {};
const calls: { agent: string; tools: string[]; last: string }[] = [];
let callSeq = 0;

function streamOf(step: Step) {
  const parts: any[] = [{ type: "stream-start", warnings: [] }, { type: "response-metadata", id: `r${callSeq}`, modelId: "mock", timestamp: new Date(0) }];
  if ("tool" in step) {
    parts.push({ type: "tool-call", toolCallId: `call_${++callSeq}`, toolName: step.tool, input: JSON.stringify(step.args) });
  } else {
    parts.push({ type: "text-start", id: "t" }, { type: "text-delta", id: "t", delta: step.text }, { type: "text-end", id: "t" });
  }
  parts.push({
    type: "finish",
    finishReason: { unified: "tool" in step ? "tool-calls" : "stop", raw: undefined },
    usage: { inputTokens: { total: 1, noCache: 1, cacheRead: 0, cacheWrite: 0 }, outputTokens: { total: 1, text: 1, reasoning: 0 } },
  });
  return new ReadableStream({ start(c) { for (const p of parts) c.enqueue(p); c.close(); } });
}

for (const key of ["assistant", "legalAgent"]) {
  queues[key] = [];
  const agent = mastra.getAgent(key);
  agent.__updateModel({
    model: new MockLanguageModelV3({
      doStream: async (opts: any) => {
        calls.push({ agent: key, tools: (opts.tools ?? []).map((t: any) => t.name), last: JSON.stringify(opts.prompt.at(-1)) });
        return { stream: streamOf(queues[key].shift() ?? { text: "ok" }) };
      },
    }),
  });
}

const USERS: Record<string, any> = {
  A: { id: "userAaaa1111", name: "A", username: "a", role: "member" },
  B: { id: "userBbbb2222", name: "B", username: "b", role: "member" },
};
const server = http.createServer((req, res) => {
  const user = USERS[String(req.headers["x-test-user"])];
  handleChat(String(req.headers["x-agent"]), req, res, user).catch((e: unknown) => { console.error(e); res.end(); });
});
await new Promise<void>((r) => server.listen(0, r));
const port = (server.address() as any).port;

let msgSeq = 0;
async function post(user: string, agent: string, message: unknown) {
  const r = await fetch(`http://127.0.0.1:${port}/`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-test-user": user, "x-agent": agent },
    body: JSON.stringify({ message }),
  });
  const text = await r.text();
  const chunks = text.split("\n").filter((l) => l.startsWith("data: ") && l !== "data: [DONE]").map((l) => JSON.parse(l.slice(6)));
  return { status: r.status, chunks, text };
}
const say = (user: string, agent: string, text: string) =>
  post(user, agent, { id: `m${++msgSeq}`, role: "user", parts: [{ type: "text", text }] });

/** Builds the browser's approval response from a stream that requested one. */
function decision(chunks: any[], approved: boolean) {
  const req = chunks.find((c) => c.type === "tool-approval-request");
  if (!req) return undefined;
  const input = chunks.find((c) => c.type === "tool-input-available" && c.toolCallId === req.toolCallId);
  return {
    id: `resp${++msgSeq}`,
    role: "assistant",
    parts: [{ type: `tool-${input.toolName}`, toolCallId: req.toolCallId, state: "approval-responded", input: input.input, approval: { id: req.approvalId, approved } }],
  };
}

const results: [string, boolean, string?][] = [];
const check = (name: string, ok: boolean, detail?: string) => { results.push([name, ok, detail]); };
const userDir = (u: string) => join(DATA, "files", USERS[u].id);
const lastCall = (agent: string) => calls.filter((c) => c.agent === agent).at(-1)!;
const callsSince = (n: number, agent: string) => calls.slice(n).filter((c) => c.agent === agent);

const WS = "mastra_workspace_";
if (phase === "phase1") {
  // (a) + (f): user A's assistant writes a file.
  queues.assistant.push({ tool: `${WS}write_file`, args: { path: "notes/plan.md", content: "secret plan of A" } }, { text: "Saved notes/plan.md" });
  let n = calls.length;
  let r = await say("A", "assistant", "save my plan");
  const aFile = join(userDir("A"), "notes/plan.md");
  check("a: A's write lands in DATA_DIR/files/<A>/", r.status === 200 && existsSync(aFile) && readFileSync(aFile, "utf8") === "secret plan of A", `status ${r.status}`);
  const tools = calls[n].tools.filter((t) => t.startsWith(WS)).sort();
  const expected = ["delete", "file_stat", "grep", "list_files", "mkdir", "read_file", "write_file"].map((t) => WS + t).sort();
  check("f: exposed workspace tools are exactly the 7 allowed (no edit_file/ast_edit/command/search/index)", JSON.stringify(tools) === JSON.stringify(expected), tools.join(","));

  // (b) user B cannot list/read/grep A's file.
  queues.assistant.push(
    { tool: `${WS}list_files`, args: { path: "." } },
    { tool: `${WS}read_file`, args: { path: "notes/plan.md" } },
    { tool: `${WS}grep`, args: { pattern: "secret" } },
    { tool: `${WS}read_file`, args: { path: `../${USERS.A.id}/notes/plan.md` } },
    { text: "done" },
  );
  n = calls.length;
  r = await say("B", "assistant", "show my files");
  const b = callsSince(n, "assistant");
  check("b: B's list does not show A's file", b.length >= 2 && !b[1].last.includes("plan.md"), b[1]?.last.slice(0, 300));
  check("b: B's read of notes/plan.md fails (not found)", !!b[2] && !b[2].last.includes("secret plan of A") && /not found|ENOENT|does not exist|No such/i.test(b[2].last), b[2]?.last.slice(0, 300));
  check("b: B's grep finds nothing of A's", !!b[3] && !b[3].last.includes("secret plan of A"), b[3]?.last.slice(0, 300));
  check("b/c: B's ../<A>/ traversal is refused", !!b[4] && !b[4].last.includes("secret plan of A") && /permission|outside|denied|access/i.test(b[4].last), b[4]?.last.slice(0, 300));
  check("b: B's folder is separate and has no plan.md", !existsSync(join(userDir("B"), "notes/plan.md")));

  // (c) traversal and absolute paths refused for writes.
  const absTarget = join(DATA, "abs-escape.md");
  queues.assistant.push(
    { tool: `${WS}write_file`, args: { path: "../escape.md", content: "x" } },
    { tool: `${WS}write_file`, args: { path: absTarget, content: "x" } },
    { tool: `${WS}read_file`, args: { path: "/etc/hosts" } },
    { tool: `${WS}read_file`, args: { path: "~/.zshrc" } },
    { text: "done" },
  );
  n = calls.length;
  r = await say("A", "assistant", "try escapes");
  const c = callsSince(n, "assistant");
  check("c: ../escape.md not written", !existsSync(join(DATA, "files", "escape.md")) && /permission|outside|denied|access/i.test(c[1]?.last ?? ""), c[1]?.last.slice(0, 300));
  check("c: absolute path not written", !existsSync(absTarget) && /permission|outside|denied|access/i.test(c[2]?.last ?? ""), c[2]?.last.slice(0, 300));
  check("c: /etc/hosts read refused", !!c[3] && !/localhost/.test(c[3].last) && /permission|outside|denied|access/i.test(c[3].last), c[3]?.last.slice(0, 300));
  check("c: ~/ read refused", !!c[4] && /permission|outside|denied|access/i.test(c[4].last), c[4]?.last.slice(0, 300));

  // (d) delete needs approval: deny keeps the file, approve deletes it.
  queues.assistant.push({ tool: `${WS}delete`, args: { path: "notes/plan.md" } });
  r = await say("A", "assistant", "delete my plan");
  let resp = decision(r.chunks, false);
  check("d: delete requests approval and has not run yet", !!resp && existsSync(aFile), resp ? "" : r.text.slice(0, 500));
  queues.assistant.push({ text: "ok, kept" });
  r = await post("A", "assistant", resp);
  check("d: deny keeps the file", r.status === 200 && existsSync(aFile), `status ${r.status}`);
  queues.assistant.push({ tool: `${WS}delete`, args: { path: "notes/plan.md" } });
  r = await say("A", "assistant", "delete my plan, really");
  resp = decision(r.chunks, true);
  queues.assistant.push({ text: "deleted" });
  const r2 = resp ? await post("A", "assistant", resp) : undefined;
  check("d: approve deletes the file in A's folder", !!resp && r2?.status === 200 && !existsSync(aFile), `status ${r2?.status}`);
  // B's attempt to answer A's approval is refused (not pending in B's thread).
  queues.assistant.push({ tool: `${WS}delete`, args: { path: "keep.md" } });
  queues.assistant.push({ tool: `${WS}write_file`, args: { path: "keep.md", content: "k" } });
  // (write first so there is something to delete)
  queues.assistant.splice(0, queues.assistant.length, { tool: `${WS}write_file`, args: { path: "keep.md", content: "k" } }, { tool: `${WS}delete`, args: { path: "keep.md" } });
  r = await say("A", "assistant", "write then delete keep.md");
  resp = decision(r.chunks, true);
  const rB = resp ? await post("B", "assistant", resp) : undefined;
  check("d: another user cannot approve A's pending delete (409)", rB?.status === 409 && existsSync(join(userDir("A"), "keep.md")), `status ${rB?.status}`);

  // (e) delegated sub-agent writes (and deletes with approval) in the same user's folder.
  queues.assistant.length = 0;
  queues.assistant.push({ tool: "agent-legalAgent", args: { prompt: "Draft an NDA checklist and save it as legal/nda-checklist.md" } }, { text: "Legal saved it" });
  queues.legalAgent.push({ tool: `${WS}write_file`, args: { path: "legal/nda-checklist.md", content: "NDA checklist" } }, { text: "Saved legal/nda-checklist.md" });
  n = calls.length;
  r = await say("A", "assistant", "have legal draft and save an NDA checklist");
  const nda = join(userDir("A"), "legal/nda-checklist.md");
  check("e: delegated legalAgent wrote into A's folder", existsSync(nda) && !existsSync(join(DATA, "files", "local", "legal/nda-checklist.md")), readdirSync(join(DATA, "files")).join(","));
  const legalTools = callsSince(n, "legalAgent")[0]?.tools.filter((t) => t.startsWith(WS)) ?? [];
  check("e/f: sub-agent sees the same 7 workspace tools", legalTools.length === 7 && !legalTools.some((t) => /edit/.test(t)), legalTools.join(","));
  queues.assistant.push({ tool: "agent-legalAgent", args: { prompt: "Delete legal/nda-checklist.md" } });
  queues.legalAgent.push({ tool: `${WS}delete`, args: { path: "legal/nda-checklist.md" } });
  r = await say("A", "assistant", "have legal delete the checklist");
  resp = decision(r.chunks, true);
  const apprPart = r.chunks.find((c: any) => c.type === "data-tool-call-approval");
  check("e: delegated delete surfaces approval on agent-legalAgent with nested tool name", !!resp && resp.parts[0].type === "tool-agent-legalAgent" && apprPart?.data?.toolName === `${WS}delete` && existsSync(nda), JSON.stringify(apprPart?.data ?? null).slice(0, 300));
  queues.legalAgent.push({ text: "deleted" });
  queues.assistant.push({ text: "Legal deleted it" });
  r2 = resp ? await post("A", "assistant", resp) : undefined;
  check("e: approving the delegated delete removes it from A's folder (resume keeps RequestContext)", r2?.status === 200 && !existsSync(nda), `status ${r2?.status}`);

  // Leave a file for phase 2 (persistence).
  queues.assistant.push({ tool: `${WS}write_file`, args: { path: "persist/keep-me.md", content: "survives restarts" } }, { text: "saved" });
  await say("A", "assistant", "save keep-me");
  check("g(setup): persist/keep-me.md written", existsSync(join(userDir("A"), "persist/keep-me.md")));
} else {
  // (g) new process, new Mastra instance: the file is still listed/readable by A, not by B.
  queues.assistant.push({ tool: `${WS}list_files`, args: { path: ".", maxDepth: 3 } }, { tool: `${WS}read_file`, args: { path: "persist/keep-me.md" } }, { text: "here" });
  let n = calls.length;
  await say("A", "assistant", "what files do I have?");
  const g = callsSince(n, "assistant");
  check("g: after restart A lists keep-me.md", g[1]?.last.includes("keep-me.md") ?? false, g[1]?.last.slice(0, 300));
  check("g: after restart A reads its content", g[2]?.last.includes("survives restarts") ?? false, g[2]?.last.slice(0, 300));
  queues.assistant.push({ tool: `${WS}read_file`, args: { path: "persist/keep-me.md" } }, { text: "nope" });
  n = calls.length;
  await say("B", "assistant", "read keep-me");
  const gb = callsSince(n, "assistant");
  check("g: after restart B still cannot read A's file", !!gb[1] && !gb[1].last.includes("survives restarts"), gb[1]?.last.slice(0, 300));
}

server.close();
let failed = 0;
for (const [name, ok, detail] of results) {
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${!ok && detail ? `\n      ${detail}` : ""}`);
}
console.log(`${phase}: ${results.length - failed}/${results.length} passed`);
process.exit(failed ? 1 : 0);

